static void testLockoutState() {
  Lockout l;
  assert(!l.blocked(100));
  l.fail(1000);
  assert(l.blocked(1000));
  assert(l.blocked(3999));
  assert(!l.blocked(4000));
  l.fail(5000);
  l.fail(6000);                       // third failure: 6 s
  assert(l.blocked(11999));
  assert(!l.blocked(12000));
  l.reset();
  assert(!l.blocked(6001));
  Lockout w; w.fail(0xFFFFFF00u);     // rollover safe
  assert(w.blocked(0xFFFFFF10u));
  assert(!w.blocked(0x00000F00u));
  Lockout s;
  for (int i = 0; i < 300; i++) s.fail(1000);
  assert(s.failures == 255);
}

static void testSession() {
  Session s;
  assert(!s.unlocked(1, 0));
  s.open(0x0A000001u, 1000);
  assert(s.unlocked(0x0A000001u, 1000 + SESSION_MS - 1));
  assert(!s.unlocked(0x0A000001u, 1000 + SESSION_MS));
  assert(!s.unlocked(0x0A000002u, 2000));   // other client stays locked
  s.open(0x0A000002u, 3000);                // a new unlock replaces the old one
  assert(!s.unlocked(0x0A000001u, 3001));
  s.close();
  assert(!s.unlocked(0x0A000002u, 3001));
  Session z;                                // address 0 never opens or matches a session
  z.open(0, 100);
  assert(!z.active && !z.unlocked(0, 100));
  z.open(0x0A000001u, 100);
  assert(!z.unlocked(0, 101));
  z.touch(100 + SESSION_MS - 1);            // touch extends the session
  assert(z.unlocked(0x0A000001u, 100 + SESSION_MS + 1000));
  z.close();
  z.touch(5);
  assert(!z.active);                        // touch never reopens
  Session w;                                // expiry must survive a counter wrap
  w.open(0x0A000001u, 0xFFFFFF00u);
  assert(w.unlocked(0x0A000001u, 0xFFFFFF00u + SESSION_MS - 1));
  assert(!w.unlocked(0x0A000001u, 0xFFFFFF00u + SESSION_MS));
  assert(!w.unlocked(0x0A000001u, 0xFFFFFF01u));   // same elapsed value one full wrap later
}

