// Payload: [len][current PIN][len][new PIN][len][OTA][len][AP][len][setup SSID]
static size_t put(uint8_t* out, size_t at, const char* s) {
  size_t n = strlen(s);
  out[at++] = static_cast<uint8_t>(n);
  memcpy(out + at, s, n);
  return at + n;
}

static void testPayload() {
  uint8_t buf[128];
  size_t n = 0;
  n = put(buf, n, "");
  n = put(buf, n, "TESTPIN1");
  n = put(buf, n, "TestOnlyOta0123456789abcdef");
  n = put(buf, n, "TestAp01");
  n = put(buf, n, "Test-Unit-0001");
  SecretsPayload p;
  assert(parseSecretsPayload(buf, n, p));
  assert(!strcmp(p.currentPin, ""));
  assert(!strcmp(p.pin, "TESTPIN1"));
  assert(!strcmp(p.ota, "TestOnlyOta0123456789abcdef"));
  assert(!strcmp(p.ap, "TestAp01"));
  assert(!strcmp(p.ssid, "Test-Unit-0001"));
  assert(!parseSecretsPayload(buf, n - 1, p));          // truncated
  assert(!parseSecretsPayload(buf, 0, p));
  uint8_t extra[130]; memcpy(extra, buf, n); extra[n] = 0;
  assert(!parseSecretsPayload(extra, n + 1, p));        // trailing bytes
  uint8_t bad[128]; size_t m = 0;
  m = put(bad, m, ""); m = put(bad, m, "SHORT"); m = put(bad, m, "TestOnlyOta0123456789abcdef");
  m = put(bad, m, "TestAp01"); m = put(bad, m, "Test-Unit-0001");
  assert(!parseSecretsPayload(bad, m, p));              // only the PIN is invalid
}

// Builds a payload from fields; returns the length.
static size_t build(uint8_t* out, const char* cur, const char* pin, const char* ota, const char* ap,
                    const char* ssid) {
  size_t n = 0;
  n = put(out, n, cur); n = put(out, n, pin); n = put(out, n, ota); n = put(out, n, ap);
  return put(out, n, ssid);
}

static void testPayloadRejects() {
  const char* OTA = "TestOnlyOta0123456789abcdef";
  uint8_t b[256];
  SecretsPayload p;
  size_t n = build(b, "", "TESTPIN1", OTA, "TestAp01", "Test Unit");
  assert(!parseSecretsPayload(b, n, p));                // space in SSID
  n = build(b, "", "TESTPIN1", OTA, "TestAp01", "Test_Unit");
  assert(!parseSecretsPayload(b, n, p));                // underscore
  n = build(b, "", "TESTPIN1", OTA, "TestAp01", "Test\xC3\xA9");
  assert(!parseSecretsPayload(b, n, p));                // byte above 0x7F
  n = build(b, "", "TESTPIN1", OTA, "TestAp01", "");
  assert(!parseSecretsPayload(b, n, p));                // empty SSID
  n = build(b, "", "TESTPIN1", OTA, "TestAp01", "abcdefghijklmnopqrstuvwxyz0123456");
  assert(!parseSecretsPayload(b, n, p));                // 33-byte SSID
  n = build(b, "BADPIN", "TESTPIN1", OTA, "TestAp01", "Test-Unit-0001");
  assert(!parseSecretsPayload(b, n, p));                // invalid current PIN
  n = build(b, "", "TESTPIN1", OTA, "TestAp01", "Test-Unit-0001");
  uint8_t c[256]; memcpy(c, b, n);
  c[0] = 200;
  assert(!parseSecretsPayload(c, n, p));                // length over cap
  memcpy(c, b, n); c[1] = 9;
  assert(!parseSecretsPayload(c, n, p));                // PIN length 9
  memcpy(c, b, n); c[n - 15] = 40;
  assert(!parseSecretsPayload(c, n, p));                // length beyond remaining data
  memcpy(c, b, n); c[2] = 0;
  assert(!parseSecretsPayload(c, n, p));                // embedded NUL
  // failure leaves nothing behind
  n = build(b, "", "TESTPIN1", "short", "TestAp01", "Test-Unit-0001");
  memset(&p, 'x', sizeof(p));
  assert(!parseSecretsPayload(b, n, p));
  assert(p.pin[0] == 0 && p.ota[0] == 0 && p.ssid[0] == 0 && p.currentPin[0] == 0 && p.ap[0] == 0);
}

static void testPayloadBounds() {
  uint8_t b[256];
  SecretsPayload p;
  const char* ota32 = "abcdefghijklmnopqrstuvwxyz012345";
  const char* ota16 = "abcdefghijklmnop";
  const char* ap63 = "abcdefghijklmnopqrstuvwxyzabcdefghijklmnopqrstuvwxyz0123456789A";
  assert(strlen(ota32) == 32 && strlen(ota16) == 16 && strlen(ap63) == 63);
  size_t n = build(b, "CURPIN12", "TESTPIN1", ota32, ap63, "abcdefghijklmnopqrstuvwxyz012345");
  assert(parseSecretsPayload(b, n, p));
  assert(!strcmp(p.currentPin, "CURPIN12") && !strcmp(p.ota, ota32) && !strcmp(p.ap, ap63));
  n = build(b, "", "TESTPIN1", ota16, "TestAp01", "a");
  assert(parseSecretsPayload(b, n, p));
  // the widest accepted payload is the transport size
  n = build(b, "CURPIN12", "TESTPIN1", ota32, ap63, "abcdefghijklmnopqrstuvwxyz012345");
  assert(n == SECRETS_PAYLOAD_MAX && SECRETS_PAYLOAD_MAX == 148);
}

// USB identity write: fresh units and factory units accept it; a lost mode record needs the PIN
// and the same identity; sealed modes never accept it.
static void testIdentityWritePolicy() {
  const Mode sealed[] = {Mode::Finishing, Mode::Setup, Mode::Home, Mode::Resetting};
  for (Mode m : sealed) {
    assert(!identityWriteOpen(m));
    for (int i = 0; i < 8; i++) assert(!identityWriteAllowed(m, i & 1, i & 2, i & 4));
  }
  assert(identityWriteOpen(Mode::None) && identityWriteOpen(Mode::Factory));
  // fresh unit: no identity, no stored PIN
  assert(identityWriteAllowed(Mode::None, false, true, false));
  assert(!identityWriteAllowed(Mode::None, false, false, false));  // a partial identity with a PIN
  // lost mode record with a complete identity: current PIN and the same identity
  assert(identityWriteAllowed(Mode::None, true, true, true));
  assert(!identityWriteAllowed(Mode::None, true, true, false));
  assert(!identityWriteAllowed(Mode::None, true, false, true));
  // factory: the identity may change with the current PIN
  assert(identityWriteAllowed(Mode::Factory, true, true, false));
  assert(identityWriteAllowed(Mode::Factory, true, true, true));
  assert(identityWriteAllowed(Mode::Factory, false, true, false));
  assert(!identityWriteAllowed(Mode::Factory, true, false, true));
}

static void testFinishPolicy() {
  assert(finishOpen(Mode::Factory) && finishOpen(Mode::Finishing) && finishOpen(Mode::Setup));
  assert(!finishOpen(Mode::None) && !finishOpen(Mode::Home) && !finishOpen(Mode::Resetting));
  assert(finishAllowed(Mode::Factory, true, true));
  assert(finishAllowed(Mode::Finishing, true, true));  // journal pending: retry
  assert(finishAllowed(Mode::Setup, true, true));      // completed handoff: idempotent
  assert(!finishAllowed(Mode::Factory, true, false));
  assert(!finishAllowed(Mode::Factory, false, true));  // no complete identity
  assert(!finishAllowed(Mode::Home, true, true));
  assert(!finishAllowed(Mode::None, true, true));
  assert(!finishAllowed(Mode::Resetting, true, true));
}

